Author: Stefan Profanter <git@s.profanter.me>
Date:   Mon May 6 15:25:55 2019 +0200

    Stack: Check for memory allocation success
---
 src/server/ua_server.c | 4 ++++
 1 file changed, 4 insertions(+)

diff --git a/src/server/ua_server.c b/src/server/ua_server.c
index c40570490..b5f065d8b 100644
--- a/src/server/ua_server.c
+++ b/src/server/ua_server.c
@@ -216,6 +216,10 @@ UA_Server_new() {

     /* Create Namespaces 0 and 1 */
     server->namespaces = (UA_String *)UA_Array_new(2, &UA_TYPES[UA_TYPES_STRING]);
