Author: Stefan Profanter <git@s.profanter.me>
Date:   Tue May 14 08:32:50 2019 +0200

    Stack: Only destroy mdns if initialized
---
 src/server/ua_discovery_manager.c | 11 ++++++-----
 1 file changed, 6 insertions(+), 5 deletions(-)

diff --git a/src/server/ua_discovery_manager.c b/src/server/ua_discovery_manager.c
index 53b1b898b..e97bc58af 100644
--- a/src/server/ua_discovery_manager.c
+++ b/src/server/ua_discovery_manager.c
@@ -72,11 +72,12 @@ initMulticastDiscoveryServer(UA_DiscoveryManager *dm, UA_Server* server) {

 static void
 destroyMulticastDiscoveryServer(UA_DiscoveryManager *dm) {
-    if(dm->mdnsDaemon)
-    {
-        mdnsd_shutdown(dm->mdnsDaemon);
-        mdnsd_free(dm->mdnsDaemon);
-    }
+       if (!dm->mdnsDaemon)
+               return;
+
+       mdnsd_shutdown(dm->mdnsDaemon);
+       mdnsd_free(dm->mdnsDaemon);
+
     if(dm->mdnsSocket != UA_INVALID_SOCKET) {
         UA_close(dm->mdnsSocket);
         dm->mdnsSocket = UA_INVALID_SOCKET;
